function totalCents(int $unitCents, int $quantity): int
{
  if ($unitCents < 0 || $unitCents > 100000 || $quantity < 0 || $quantity > 1000) {
    throw new InvalidArgumentException("Values outside teaching limits");
  }
  return $unitCents * $quantity;
}
$total = totalCents(125, 3);
check($total === 375, "Wrong total");
check(totalCents(125, 0) === 0, "Zero quantity failed");

final class StudySession
{
  public function __construct(public readonly string $topic, public readonly int $minutes)
  {
    if (trim($topic) === "" || $minutes < 0) {
      throw new InvalidArgumentException("Invalid session");
    }
  }
  public function label(): string
  {
    return $this->topic . ": " . $this->minutes . " minutes";
  }
}

$session = new StudySession("CSS", 45);
check($session->label() === "CSS: 45 minutes", "Label failed");
$failed = false;
try {
  new StudySession("", 10);
} catch (InvalidArgumentException) {
  $failed = true;
}
check($failed, "Empty topic accepted");
echo $session->label() . "\n";

echo "web-040 reference checks passed\n";

enum Topic: string
{
  case Html = "HTML";
  case Css = "CSS";
  case Php = "PHP";
}

function validatePlan(array $input): array
{
  $errors = [];
  $topic = $input["topic"] ?? null;
  $minutes = $input["minutes"] ?? null;
  $choice = is_string($topic) ? Topic::tryFrom($topic) : null;
  if ($choice === null) {
    $errors["topic"] = "Choose HTML, CSS or PHP.";
  }

check(
  validatePlan(["topic" => "HTML", "minutes" => "30"])["value"]["minutes"] === 30,
  "Valid plan failed",
);
check(
  validatePlan(["topic" => ["HTML"], "minutes" => "30"])["value"] === null,
  "Array input accepted",
);
check(validatePlan([])["value"] === null, "Missing input accepted");
check(
  validatePlan(["topic" => "html", "minutes" => "30"])["value"] === null,
  "Unknown topic accepted",
);
echo json_encode(validatePlan(["topic" => "CSS", "minutes" => "121"]), JSON_THROW_ON_ERROR) . "\n";

echo "web-047 reference checks passed\n";
